import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import Ajv, {type ValidateFunction} from 'ajv';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

const ajvOptions = Object.assign(
  {
    strictNumbers: false,
    strictTuples: false,
    strictRequired: false,
    validateFormats: false,
  },
  {strict: false}
);
const ajv = new Ajv(ajvOptions);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
  dynamicValidators: WeakMap<object, ValidateFunction>;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let staticValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      staticValidator = this.compileSchema(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      staticValidator,
      dynamicValidators: new WeakMap(),
    });
  }

  private compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return ajv.compile(schema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${name}: ${reason}`, {cause: error});
    }
  }

  private validatorFor(name: string, tool: StoredTool): ValidateFunction {
    if (tool.staticValidator) return tool.staticValidator;
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    const cachedValidator = tool.dynamicValidators.get(schema);
    if (cachedValidator) return cachedValidator;
    const validator = this.compileSchema(name, schema);
    tool.dynamicValidators.set(schema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Rejects schema-invalid input as a tool result; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.validatorFor(name, tool);
    if (validate(input)) {
      log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
      const rawResult = await tool.execute(input, context);
      const response = normalizeToolResponse(rawResult);
      log.info('tool', 'execution complete', {
        name,
        rawType: typeof rawResult,
        clientMessageCount: response.clientMessages?.length ?? 0,
        clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
        suppressAssistantResponse: response.suppressAssistantResponse ?? false,
      });
      return response;
    }

    const error = validate.errors?.[0] as
      {keyword?: string; instancePath?: string; params?: Record<string, unknown>; message?: string} | undefined;
    const pointer = error?.instancePath || (error as {dataPath?: string} | undefined)?.dataPath || '';
    const pathParts = pointer
      .split('/')
      .filter(Boolean)
      .map(part => part.replace(/~1/g, '/').replace(/~0/g, '~'));
    const path = pathParts.join('.') || 'input';
    const params = error?.params ?? {};
    const result =
      error?.keyword === 'required'
        ? `Missing required property: ${[...pathParts, String(params.missingProperty)].filter(Boolean).join('.')}`
        : error?.keyword === 'type'
          ? `Invalid input at ${path}: expected ${String(params.type)}`
          : error?.keyword === 'enum'
            ? `Invalid input at ${path}: value is not in the allowed enum`
            : `Invalid input at ${path}: ${error?.message ?? 'does not match the input schema'}`;
    return {result};
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16); [validated by: returns a required-property rejection without invoking the tool](../../src/orchestration/tools/registry.test.ts#L15)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When valid input includes undeclared extra properties, `ToolRegistry.execute` passes the input through unchanged and invokes the executor exactly once ([validated by: passes valid input with extra properties through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L34)).
- For a nested wrong-typed value, the rejection names its full property path and expected type without echoing the value ([validated by: names the full nested property path when a value has the wrong type](../../src/orchestration/tools/registry.test.ts#L97)).
- When a property value is outside its declared `enum`, the rejection names the property and the enum constraint ([validated by: names the property and enum constraint when input is outside an enum](../../src/orchestration/tools/registry.test.ts#L118)).
- A rejected property value is omitted from both returned text and emitted log lines ([validated by: does not log or return a rejected property value](../../src/orchestration/tools/registry.test.ts#L141)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: static schemas compile once across repeated executions](../../src/orchestration/tools/registry.test.ts#L80)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.
- A function-valued tool definition is validated against the schema returned for each execution, even when successive calls return different schemas ([validated by: validates function-valued tools against the schema resolved on each call](../../src/orchestration/tools/registry.test.ts#L50)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
- `processMessage` resolves after the provider receives a rejected tool call as a result and retries with corrected arguments ([validated by: returns an input rejection to the provider so it can retry with corrected arguments](../../src/orchestration/chatOrchestrator.test.ts#L402)).
- The provider can retry after the rejection and the final result includes text from every model round ([validated by: joins the text of every round, not only the last](../../src/orchestration/chatOrchestrator.test.ts#L531)).

import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';

const registerWeatherTool = (
  registry: ToolRegistry,
  inputSchema: Record<string, unknown>,
  execute: ToolExecutor
): void => {
  registry.register({name: 'weather', description: 'Get weather', inputSchema}, execute);
};

describe('ToolRegistry', () => {
  it('returns a required-property rejection without invoking the tool', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registerWeatherTool(
      registry,
      {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      execute
    );

    const response = await registry.execute('weather', {});
    const calls = execute.mock.calls;

    expect({
      namesRequiredField: /location.*required|required.*location/i.test(response.result),
      executorCalls: calls.length,
    }).toEqual({namesRequiredField: true, executorCalls: 0});
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#3
  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', unit: 'celsius'};
    const execute = jest.fn(async (received: Record<string, unknown>) => JSON.stringify(received));
    registerWeatherTool(
      registry,
      {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      execute
    );

    await registry.execute('weather', input);

    expect(execute.mock.calls).toEqual([[input, undefined]]);
  });

