const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
  const chunks: MessageChunk[] = [];
  for await (const chunk of stream) chunks.push(chunk);
  return chunks;
};

describe('ChatOrchestrator tool loop', () => {
  // @spec specs/hal-engine-tool-input-validation/spec.md#10
  it('returns an input rejection to the provider so it can retry with corrected arguments', async () => {
    const receivedToolResults: string[] = [];
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        if (round > 0) {
          const results = params.messages.flatMap(message =>
            message.role === 'user' && Array.isArray(message.content)
              ? message.content.filter(content => content.type === 'tool_result').map(result => result.content)
              : []
          );
          receivedToolResults.push(...results);
        }

        const currentRound = round++;
        if (currentRound === 0) {
          yield {type: 'tool_use', toolCall: {id: 'bad-call', name: 'weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (currentRound === 1) {
          yield {type: 'tool_use', toolCall: {id: 'good-call', name: 'weather', input: {location: 'Berlin'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: 'Sunny in Berlin'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async ({location}) => `Sunny in ${String(location)}`
    );
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const response = await orchestrator.processMessage(createSession('weather in Berlin'));

    expect({response, rejectionSentToProvider: receivedToolResults[0]}).toEqual({
      response: 'Sunny in Berlin',
      rejectionSentToProvider: expect.stringContaining('location'),
    });
  });

  it('runs another round after a tool call and streams both rounds in order', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'the answer'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
  });

